private void handleStream(String content, Parser handler, boolean isContentSource, XHTMLContentHandler xhtml, Metadata metadata, ParseContext context) throws IOException, SAXException, TikaException {
    if (content == null || content.isEmpty()) {
        return;
    }
    if (handler != null) {
        ContentHandler target = isContentSource ? new BodyContentHandler(xhtml) : DISCARD_HANDLER;
        try (TikaInputStream tis = TikaInputStream.get(content.getBytes(StandardCharsets.UTF_8))) {
            handler.parse(tis, target, metadata, context);
        }
    } else if (isContentSource) {
        // No handler — write raw content as XHTML text
        String[] lines = content.split("\n", -1);
        for (int i = 0; i < lines.length; i++) {
            xhtml.characters(lines[i]);
            if (i < lines.length - 1) {
                xhtml.newline();
            }
        }
    }
}
